//! Issue #354: a validator that receives a block whose parent it never got
//! fetches the missing blocks from the peer that sent it, so the network keeps
//! producing.
//!
//! Three real `sumchain` validators of one NONPRODUCTION genesis (chain id
//! 1337, keys generated by the binary into a temp directory, block time 1 s),
//! on loopback, in a star around a hub. The node has no peer discovery besides
//! its bootnodes (no mDNS, no Kademlia), so the two leaves never connect to
//! each other. Height `h` is proposed by validator `h mod 3`:
//!
//! | name | index | role |
//! |---|---|---|
//! | `leaf`     | 0 | proposer of 3, 6, …; bootnode: the hub |
//! | `isolated` | 1 | proposer of 1, 4, …; bootnode: the hub, which is not up when it starts |
//! | `hub`      | 2 | proposer of 2, 5, … |
//!
//! The run reproduces #354's first trigger deterministically:
//!
//! 1. `isolated` starts alone and produces block 1, which reaches nobody.
//! 2. `hub` and `leaf` start; `leaf` connects to `hub`. Both are at height 0,
//!    so neither has anything to fetch from the other.
//! 3. About 30 s later `isolated` re-dials its bootnode; `hub` fetches block 1
//!    from it on connect (sync, which is not re-gossiped) and produces block 2.
//! 4. `leaf` receives block 2 by gossip without ever having seen block 1.
//!
//! Before #354 `leaf` logged "Failed to import block: Parent block not found"
//! and asked for nothing; as the proposer of height 3 it then held the whole
//! network at heights `[0, 2, 2]` for good. With the fix it requests the
//! missing blocks from the peer that gossiped block 2, imports them, produces
//! block 3, and the chain continues.
#![cfg(unix)]

use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

const BIN: &str = env!("CARGO_BIN_EXE_sumchain");

struct Validator {
    name: &'static str,
    log: PathBuf,
    child: Child,
}

impl Validator {
    fn log_text(&self) -> String {
        let mut s = String::new();
        if let Ok(mut f) = fs::File::open(&self.log) {
            let _ = f.read_to_string(&mut s);
        }
        s
    }

    fn produced(&self, height: u64) -> bool {
        let suffix = format!(" at height {height}");
        self.log_text()
            .lines()
            .any(|l| l.contains("Produced block") && l.ends_with(&suffix))
    }
}

impl Drop for Validator {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn keygen(path: &Path) -> String {
    let out = Command::new(BIN)
        .args(["keygen", "--output"])
        .arg(path)
        .output()
        .unwrap();
    assert!(out.status.success(), "keygen failed: {out:?}");
    String::from_utf8_lossy(&out.stdout)
        .lines()
        .find_map(|l| l.strip_prefix("Public key: ").map(str::to_owned))
        .expect("keygen prints the public key")
}

/// A port nothing listens on right now, for the hub's P2P listener: the
/// isolated validator needs it as its bootnode before the hub exists.
fn free_port() -> u16 {
    std::net::TcpListener::bind("127.0.0.1:0")
        .unwrap()
        .local_addr()
        .unwrap()
        .port()
}

fn start(dir: &Path, name: &'static str, listen_port: u16, bootnode: Option<u16>) -> Validator {
    let bootnodes = match bootnode {
        Some(p) => format!("[\"/ip4/127.0.0.1/tcp/{p}\"]"),
        None => "[]".into(),
    };
    let cfg = dir.join(format!("{name}.toml"));
    fs::write(
        &cfg,
        format!(
            r#"[node]
genesis = "{g}"
data_dir = "{d}"
validator_key = "{k}"
[consensus]
engine = "poa"
[network]
listen_addr = "/ip4/127.0.0.1/tcp/{listen_port}"
bootnodes = {bootnodes}
mdns = false
[rpc]
addr = "127.0.0.1:0"
[health]
addr = "127.0.0.1:0"
[logging]
level = "info"
json = false
"#,
            g = dir.join("genesis.json").display(),
            d = dir.join(format!("data-{name}")).display(),
            k = dir.join(format!("{name}.json")).display(),
        ),
    )
    .unwrap();
    let log = dir.join(format!("{name}.log"));
    let f = fs::File::create(&log).unwrap();
    let child = Command::new(BIN)
        .args(["run", "--config"])
        .arg(&cfg)
        .env("NO_COLOR", "1")
        .stdout(Stdio::from(f.try_clone().unwrap()))
        .stderr(Stdio::from(f))
        .spawn()
        .unwrap();
    Validator { name, log, child }
}

fn wait_until(what: &str, within: Duration, nodes: &[&Validator], mut cond: impl FnMut() -> bool) {
    let t = Instant::now();
    while t.elapsed() < within {
        if cond() {
            return;
        }
        std::thread::sleep(Duration::from_millis(250));
    }
    let logs: String = nodes
        .iter()
        .map(|v| format!("\n===== {} =====\n{}", v.name, v.log_text()))
        .collect();
    panic!("{what}: not within {within:?}{logs}");
}

#[test]
fn a_validator_missing_a_parent_fetches_it_from_the_sender_and_the_network_keeps_producing() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path();
    let names = ["leaf", "isolated", "hub"];
    let pk: Vec<String> = names
        .iter()
        .map(|n| keygen(&p.join(format!("{n}.json"))))
        .collect();
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis();
    fs::write(
        p.join("genesis.json"),
        format!(
            r#"{{"chain_id":1337,"genesis_time":{now},"validators":["{}","{}","{}"],"alloc":{{}},
 "params":{{"block_time_ms":1000,"max_block_bytes":1000000,"max_txs_per_block":1000,"min_fee":1}}}}"#,
            pk[0], pk[1], pk[2]
        ),
    )
    .unwrap();

    let hub_port = free_port();

    // 1. `isolated` produces block 1 with no peers.
    let isolated = start(p, "isolated", 0, Some(hub_port));
    wait_until("isolated produces block 1 alone", Duration::from_secs(60), &[&isolated], || {
        isolated.produced(1)
    });

    // 2. `hub` and `leaf`, both at height 0, connect. `leaf` starts once the
    //    hub listens: a bootnode dialled too early is retried only after 30 s,
    //    by which time `isolated` would have reached the hub first.
    let hub = start(p, "hub", hub_port, None);
    wait_until("hub listens", Duration::from_secs(60), &[&hub], || {
        hub.log_text().contains("P2P listening on")
    });
    let leaf = start(p, "leaf", 0, Some(hub_port));
    let all = [&leaf, &isolated, &hub];
    wait_until("leaf connects to hub", Duration::from_secs(60), &all, || {
        leaf.log_text().contains("Peer connected")
    });

    // 3. `isolated` re-dials (every 30 s while it has no peer); `hub` fetches
    //    block 1 from it and produces block 2, which `leaf` receives by gossip.
    wait_until("hub obtains block 1 and produces block 2", Duration::from_secs(90), &all, || {
        hub.log_text().contains("Sync complete at height 1") && hub.produced(2)
    });

    // 4. `leaf` must fetch block 1 to import block 2 and propose height 3.
    wait_until(
        "leaf fetches the missing block and produces block 3",
        Duration::from_secs(45),
        &all,
        || leaf.produced(3),
    );
    assert!(
        leaf.log_text().contains("requesting them from"),
        "leaf recovered without the missing-parent request:\n{}",
        leaf.log_text()
    );
    wait_until(
        "the network keeps producing (isolated at 4, hub at 5)",
        Duration::from_secs(45),
        &all,
        || isolated.produced(4) && hub.produced(5),
    );
}
